package org.example.productservice.controller;import lombok.RequiredArgsConstructor;import org.example.productservice.dto.ProductDto;import org.example.productservice.dto.SaveProductDto;import org.example.productservice.service.ProductService;import org.springframework.core.io.Resource;import org.springframework.data.domain.Page;import org.springframework.data.domain.Pageable;import org.springframework.data.web.PageableDefault;import org.springframework.http.HttpStatus;import org.springframework.http.MediaType;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.DeleteMapping;import org.springframework.web.bind.annotation.GetMapping;import org.springframework.web.bind.annotation.PathVariable;import org.springframework.web.bind.annotation.PostMapping;import org.springframework.web.bind.annotation.PutMapping;import org.springframework.web.bind.annotation.RequestBody;import org.springframework.web.bind.annotation.RequestMapping;import org.springframework.web.bind.annotation.RequestParam;import org.springframework.web.bind.annotation.RestController;import org.springframework.web.multipart.MultipartFile;import java.io.IOException;@RestController@RequiredArgsConstructor@RequestMapping("/products")public class ProductController {    private final ProductService productService;    @GetMapping("/all")    public ResponseEntity<Page<ProductDto>> getAll(@PageableDefault(size = 5) Pageable pageable) {        Page<ProductDto> products = productService.getAll(pageable);        return ResponseEntity.ok(products);    }    @PostMapping("/add")    public ResponseEntity<ProductDto> save(@RequestBody SaveProductDto dto) {        ProductDto createdProduct = productService.create(dto);        return new ResponseEntity<>(createdProduct, HttpStatus.CREATED);    }    @GetMapping("/images/{filename}")    public ResponseEntity<Resource> getImage(@PathVariable String filename) throws IOException {        return ResponseEntity.ok()                .contentType(MediaType.parseMediaType(productService.getImageContentType(filename)))                .body(productService.getImage(filename));    }    @GetMapping("/{id}")    public ResponseEntity<ProductDto> getById(@PathVariable Long id) {        return ResponseEntity.ok(productService.getById(id));    }    @PutMapping("/{id}/decrease")    public ResponseEntity<Void> decrease(@PathVariable Long id, @RequestParam Integer qty) {        productService.decreaseStock(id, qty);        return ResponseEntity.noContent().build();    }    @PostMapping("/{id}/image")    public ResponseEntity<ProductDto> uploadImage(@PathVariable Long id, @RequestParam("image") MultipartFile file) throws IOException {        return ResponseEntity.ok(productService.uploadImage(id, file));    }    @PutMapping("/update/{id}")    public ResponseEntity<ProductDto> update(@PathVariable Long id, @RequestBody SaveProductDto dto) {        return ResponseEntity.ok(productService.update(id, dto));    }    @DeleteMapping("/delete/{id}")    public ResponseEntity<Void> delete(@PathVariable Long id) {        productService.delete(id);        return ResponseEntity.noContent().build();    }}